"use client";

import { books } from "@/data/books";
import { useCart } from "@/context/CartContext";
import { ShoppingCart } from "lucide-react";
import Link from "next/link";


export default function BookDetails({
  params,
}: {
  params: {
    id: string;
  };
}) {


  const book = books.find(
    (book) => book.id === Number(params.id)
  );


  const { addToCart } = useCart();


  if (!book) {
    return (
      <main className="p-10">
        <h1 className="text-3xl font-bold">
          Book not found
        </h1>
      </main>
    );
  }



  return (
    <main className="min-h-screen bg-gray-100 p-8">


      <Link
        href="/"
        className="mb-6 inline-block rounded bg-black px-4 py-2 text-white"
      >
        ← Back
      </Link>



      <div className="mx-auto grid max-w-5xl gap-10 rounded-xl bg-white p-8 shadow md:grid-cols-2">


        <img
          src={book.image}
          alt={book.title}
          className="h-[500px] w-full rounded-xl object-cover"
        />



        <div>

          <h1 className="text-4xl font-bold">
            {book.title}
          </h1>


          <p className="mt-3 text-xl text-gray-600">
            {book.author}
          </p>



          <p className="mt-6">
            Lorem ipsum dolor sit amet.
            This is a demo description for the book.
          </p>



          <div className="mt-6">

            <span
              className={
                book.available
                  ? "text-green-600"
                  : "text-red-600"
              }
            >
              {book.available
                ? "Available"
                : "Currently borrowed"}
            </span>

          </div>



          <button
            onClick={() =>
              addToCart({
                id: book.id,
                title: book.title,
                author: book.author,
                image: book.image,
              })
            }
            className="mt-8 flex items-center gap-2 rounded-xl bg-black px-8 py-3 text-white"
          >

            <ShoppingCart />

            Buy this book

          </button>


        </div>


      </div>


    </main>
  );
}